const express = require('express');
const { z } = require('zod');
const { DynamicStructuredTool } = require('@langchain/core/tools');
const { verifySession } = require('../middleware/session');
const { Invoice } = require('../models/invoice');

const app = express();
app.use(express.json());

app.post('/api/ai/tools/invoice-lookup', verifySession, async (req, res) => {
  const { toolInput } = req.body;
  try {
    const getInvoiceDetailsTool = new DynamicStructuredTool({
      name: 'get_invoice_details',
      description: 'Retrieves itemized breakdown, customer tax ID, and payment status for an invoice',
      schema: z.object({
        invoiceId: z.string().describe('The alphanumeric identifier of the invoice')
      }),
      func: async ({ invoiceId }) => {
        // Enforce organization scoping against verified session
        const invoice = await Invoice.findOne({
          where: {
            id: invoiceId,
            organizationId: req.user.organizationId
          }
        });
        if (!invoice) return JSON.stringify({ error: 'Invoice not found or access denied' });
        return JSON.stringify({
          id: invoice.id,
          amount: invoice.amount,
          taxId: invoice.customerTaxId,
          lineItems: invoice.lineItems,
          status: invoice.status
        });
      }
    });

    const result = await getInvoiceDetailsTool.invoke(toolInput);
    res.json({ output: JSON.parse(result) });
  } catch (err) {
    res.status(400).json({ error: err.message });
  }
});

app.listen(8116);
